:root {
  --bg: #0f172a;
  --panel: #172033;
  --panel-strong: #1d2b3d;
  --panel-soft: #23364b;
  --line: rgba(255, 255, 255, 0.08);
  --text: #edf6ff;
  --muted: #9bb1c9;
  --gold: #fbbf24;
  --green: #4ade80;
  --red: #f87171;
  --blue: #60a5fa;
  --purple: #a78bfa;
  --shadow: rgba(15, 23, 42, 0.42);
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
  background: radial-gradient(circle at top, #1e2d46, var(--bg) 40%);
  color: var(--text);
  font-family: Inter, "Segoe UI", sans-serif;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 22px;
}

.game-shell {
  width: min(1440px, 100%);
  background: rgba(10, 16, 27, 0.82);
  border: 1px solid var(--line);
  border-radius: 20px;
  box-shadow: 0 28px 60px var(--shadow);
  overflow: hidden;
  backdrop-filter: blur(6px);
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 22px 18px;
  background: rgba(255, 255, 255, 0.02);
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 4px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  font-size: 0.72rem;
}

h1 {
  margin: 0;
  font-size: clamp(1.7rem, 2vw, 2.5rem);
}

.topbar-stats {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.pill {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  min-width: 110px;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(256, 256, 256, 0.04);
  border: 1px solid rgba(255,255,255,0.06);
}

.pill span {
  font-size: 0.72rem;
  color: var(--muted);
}

.pill strong {
  font-size: 1.05rem;
}

.main-game {
  display: grid;
  grid-template-columns: minmax(0, 2.2fr) minmax(300px, 0.9fr);
  gap: 18px;
  padding: 18px;
}

.shop-panel,
.card {
  background: linear-gradient(180deg, rgba(21,35,53,0.98), rgba(17,27,40,0.96));
  border: 1px solid var(--line);
  border-radius: 18px;
}

.shop-panel {
  padding: 16px;
}

#gameCanvas {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 12px;
  background: linear-gradient(180deg, #1d2a39, #0d1726);
  border: 1px solid rgba(255,255,255,0.08);
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card {
  padding: 16px;
}

.card h2 {
  margin: 0 0 14px;
  font-size: 1rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--muted);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.stats-grid div {
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.06);
}

.stats-grid span {
  display: block;
  color: var(--muted);
  font-size: 0.72rem;
  margin-bottom: 5px;
}

.button-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

button {
  appearance: none;
  border: none;
  border-radius: 10px;
  background: linear-gradient(180deg, #2c4d73, #1d3a5b);
  color: var(--text);
  font-weight: 700;
  padding: 10px 12px;
  cursor: pointer;
  transition: transform 0.18s ease, filter 0.18s ease;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.12);
}

button:hover {
  transform: translateY(-1px);
  filter: brightness(1.07);
}

button:active {
  transform: translateY(0);
}

.inventory-list {
  display: grid;
  gap: 8px;
}

.inventory-item {
  display: flex;
  justify-content: space-between;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.06);
  color: var(--text);
}

.inventory-item span:first-child {
  text-transform: capitalize;
}

.inventory-item strong {
  font-size: 0.9rem;
}

.log-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
  font-size: 0.88rem;
  color: var(--muted);
}

.log-list li {
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.04);
}

@media (max-width: 980px) {
  .main-game {
    grid-template-columns: 1fr;
  }

  .topbar {
    align-items: flex-start;
    flex-direction: column;
    gap: 16px;
  }
}

